IGGER_EVENT'',N''1982630106'',N''2'',N'''',N''0'',N''0''),(N''msdb'',N''TRIGGER_EVENT'',N''1998630163'',N''2'',N'''',N''0'',N''0''),(N''msdb'',N''TRIGGER_EVENT'',N''2014630220'',N''2'',N'''',N''0'',N''0''),(N''msdb'',N''TRIGGER_EVENT'',N''2030630277'',N''2'',N'''',N''0'',N''0''),(N''msdb'',N''TRIGGER_EVENT'',N''2036202304'',N''1'',N'''',N''0'',N''0''),(N''msdb'',N''TRIGGER_EVENT'',N''2046630334'',N''2'',N'''',N''0'',N''0''),(N''msdb'',N''TRIGGER_EVENT'',N''2052202361'',N''2'',N'''',N''0'',N''0''),(N''msdb'',N''TRIGGER_EVENT'',N''2062630391'',N''2'',N'''',N''0'',N''0''),(N''msdb'',N''TRIGGER_EVENT'',N''2068202418'',N''1'',N'''',N''0'',N''0''),(N''msdb'',N''TRIGGER_EVENT'',N''2084202475'',N''3'',N'''',N''0'',N''0''),(N''tempdb'',N''PRINCIPAL'',N''public'',N''dbo'',N''R'',N'''',N''0:0''),(N''tempdb'',N''PRINCIPAL'',N''dbo'',N'''',N''S'',N''sa'',N''1:0''),(N''tempdb'',N''PRINCIPAL'',N''guest'',N'''',N''S'',N'''',N''0:0''),(N''tempdb'',N''PRINCIPAL'',N''INFORMATION_SCHEMA'',N'''',N''S'',N'''',N''0:0''),(N''tempdb'',N''PRINCIPAL'',N''sys'',N'''',N''S'',N'''',N''0:0''),(N''tempdb'',N''PRINCIPAL'',N''db_owner'',N''dbo'',N''R'',N'''',N''0:1''),(N''tempdb'',N''PRINCIPAL'',N''db_accessadmin'',N''dbo'',N''R'',N'''',N''0:1''),(N''tempdb'',N''PRINCIPAL'',N''db_securityadmin'',N''dbo'',N''R'',N'''',N''0:1''),(N''tempdb'',N''PRINCIPAL'',N''db_ddladmin'',N''dbo'',N''R'',N'''',N''0:1''),(N''tempdb'',N''PRINCIPAL'',N''db_backupoperator'',N''dbo'',N''R'',N'''',N''0:1''),(N''tempdb'',N''PRINCIPAL'',N''db_datareader'',N''dbo'',N''R'',N'''',N''0:1''),(N''tempdb'',N''PRINCIPAL'',N''db_datawriter'',N''dbo'',N''R'',N'''',N''0:1''),(N''tempdb'',N''PRINCIPAL'',N''db_denydatareader'',N''dbo'',N''R'',N'''',N''0:1''),(N''tempdb'',N''PRINCIPAL'',N''db_denydatawriter'',N''dbo'',N''R'',N'''',N''0:1''),(N''tempdb'',N''MEMBER'',N''db_owner'',N''dbo'',N'''',N'''',N'''');

IF ISNULL(CONVERT(varchar(64),SERVERPROPERTY(''ProductVersion'')),'''')<>@SystemProductVersion
 THROW 59620,''Unreviewed boxed system catalog version.'',1;
DECLARE @RuntimeSids table(Sid varbinary(85) PRIMARY KEY);
INSERT @RuntimeSids SELECT DISTINCT p.sid FROM sys.database_role_members m JOIN sys.database_principals p ON p.principal_id=m.member_principal_id
WHERE m.role_principal_id IN(DATABASE_PRINCIPAL_ID(''AiCimdCaseRuntimeV1''),DATABASE_PRINCIPAL_ID(''AiCimdOAuthBrowserV1''),DATABASE_PRINCIPAL_ID(''AiCimdOAuthIssuerV1''),DATABASE_PRINCIPAL_ID(''AiCimdOAuthResolverV1''),DATABASE_PRINCIPAL_ID(''AiCimdMetadataPublisherV1''),DATABASE_PRINCIPAL_ID(''AiCimdOAuthNeutralV1''),DATABASE_PRINCIPAL_ID(''AiApplicationPublisher''),DATABASE_PRINCIPAL_ID(''AiApplicationTenant''),DATABASE_PRINCIPAL_ID(''AiCimdCatalogV2''));
IF EXISTS(SELECT 1 FROM @RuntimeSids WHERE Sid=@OwnerSid OR Sid=(SELECT sid FROM sys.server_principals WHERE principal_id=@SignerId))
 THROW 59620,''Execution identities overlap runtime identities.'',1;
INSERT @RuntimeSids SELECT @OwnerSid UNION SELECT sid FROM sys.server_principals WHERE principal_id=@SignerId;
DECLARE @SystemName sysname,@SystemSql nvarchar(max);
CREATE TABLE #CimdCheckedSids(Sid varbinary(85) PRIMARY KEY);
INSERT #CimdCheckedSids SELECT Sid FROM @RuntimeSids;
CREATE TABLE #CimdSystemPermissions(DatabaseName sysname,Class int,MajorId int,MinorId int,Grantee sysname,Grantor sysname,PermissionName sysname,State char(1));
CREATE TABLE #CimdSystemObjects(DatabaseName sysname,ObjectId int,SchemaName sysname,Name sysname,Type char(2),OwnerId int,DefinitionHash varchar(64),ExecuteAs int,Ansi bit,Quoted bit);
CREATE TABLE #CimdSystemAuthority(DatabaseName sysname,Kind nvarchar(32),Name nvarchar(517),Related nvarchar(517),Type nvarchar(128),Value nvarchar(max),Flags nvarchar(128));
DECLARE SystemCatalogs CURSOR LOCAL FAST_FORWARD FOR SELECT name FROM sys.databases WHERE name<>DB_NAME();
OPEN SystemCatalogs;FETCH NEXT FROM SystemCatalogs INTO @SystemName;
WHILE @@FETCH_STATUS=0 BEGIN
 SET @SystemSql=N''USE ''+QUOTENAME(@SystemName)+N'';
 IF ISNULL(HAS_PERMS_BY_NAME(DB_NAME(),''''DATABASE'''',''''VIEW DEFINITION''''),0)<>1 THROW 59620,''''Cross-database metadata visibility required.'''',1;
 IF EXISTS(SELECT 1 FROM sys.database_principals p JOIN #CimdCheckedSids s ON s.Sid=p.sid) THROW 59620,''''Cross-database principal mapping refused.'''',1;
 IF DB_ID()<=4 BEGIN
  IF EXISTS(SELECT 1 FROM sys.database_role_members WHERE member_principal_id IN(DATABASE_PRINCIPAL_ID(''''public''''),DATABASE_PRINCIPAL_ID(''''guest'''')))
   OR EXISTS(SELECT 1 FROM sys.schemas WHERE principal_id IN(DATABASE_PRINCIPAL_ID(''''public''''),DATABASE_PRINCIPAL_ID(''''guest'''')) AND NOT(name=''''guest'''' AND principal_id=DATABASE_PRINCIPAL_ID(''''guest'''')))
   OR EXISTS(SELECT 1 FROM sys.objects WHERE schema_id=SCHEMA_ID(''''guest'''') AND is_ms_shipped=0)
   OR EXISTS(SELECT 1 FROM sys.objects WHERE principal_id IN(DATABASE_PRINCIPAL_ID(''''public''''),DATABASE_PRINCIPAL_ID(''''guest'''')))
   OR EXISTS(SELECT 1 FROM sys.database_principals WHERE owning_principal_id IN(DATABASE_PRINCIPAL_ID(''''public''''),DATABASE_PRINCIPAL_ID(''''guest'''')))
   OR EXISTS(SELECT 1 FROM sys.types WHERE is_user_defined=1 AND principal_id IN(DATABASE_PRINCIPAL_ID(''''public''''),DATABASE_PRINCIPAL_ID(''''guest'''')))
   OR EXISTS(SELECT 1 FROM sys.certificates WHERE principal_id IN(DATABASE_PRINCIPAL_ID(''''public''''),DATABASE_PRINCIPAL_ID(''''guest'''')))
   OR EXISTS(SELECT 1 FROM sys.asymmetric_keys WHERE principal_id IN(DATABASE_PRINCIPAL_ID(''''public''''),DATABASE_PRINCIPAL_ID(''''guest'''')))
   OR EXISTS(SELECT 1 FROM sys.assemblies WHERE principal_id IN(DATABASE_PRINCIPAL_ID(''''public''''),DATABASE_PRINCIPAL_ID(''''guest'''')))
   THROW 59620,''''System public or guest ownership/inheritance refused.'''',1;
  INSERT #CimdSystemPermissions SELECT DB_NAME(),p.class,p.major_id,p.minor_id,USER_NAME(p.grantee_principal_id),USER_NAME(p.grantor_principal_id),p.permission_name,p.state FROM sys.database_permissions p;
  INSERT #CimdSystemObjects SELECT DB_NAME(),o.object_id,s.name,o.name,o.type,COALESCE(o.principal_id,s.principal_id),CONVERT(varchar(64),HASHBYTES(''''SHA2_256'''',m.definition),2),m.execute_as_principal_id,m.uses_ansi_nulls,m.uses_quoted_identifier FROM sys.objects o JOIN sys.schemas s ON s.schema_id=o.schema_id LEFT JOIN sys.sql_modules m ON m.object_id=o.object_id WHERE o.object_id>0 AND o.type NOT IN(''''PK'''',''''UQ'''') AND NOT(DB_NAME()=''''tempdb'''' AND o.name LIKE ''''#%'''' AND o.name NOT LIKE ''''##%'''');
  INSERT #CimdSystemAuthority SELECT DB_NAME() COLLATE Latin1_General_100_BIN2 AS DatabaseName,N''''PRINCIPAL'''' COLLATE Latin1_General_100_BIN2 AS Kind,p.name COLLATE Latin1_General_100_BIN2 AS Name,ISNULL(USER_NAME(p.owning_principal_id),N'''''''') COLLATE Latin1_General_100_BIN2 AS Related,CONVERT(nvarchar(128),p.type) COLLATE Latin1_General_100_BIN2 AS Type,ISNULL((SELECT name FROM sys.server_principals WHERE sid=p.sid),N'''''''') COLLATE Latin1_General_100_BIN2 AS Value,CONCAT(p.authentication_type,N'''':'''',p.is_fixed_role) COLLATE Latin1_General_100_BIN2 AS Flags
FROM sys.database_principals p
UNION ALL SELECT DB_NAME(),N''''MEMBER'''',USER_NAME(role_principal_id),USER_NAME(member_principal_id),N'''''''',N'''''''',N'''''''' FROM sys.database_role_members
UNION ALL SELECT DB_NAME(),N''''SIGNATURE'''',CONVERT(nvarchar(128),p.major_id),CONVERT(nvarchar(128),p.class),CONVERT(nvarchar(128),p.crypt_type),COALESCE(c.name,k.name,N''''<UNRESOLVED>''''),N'''''''' FROM sys.crypt_properties p LEFT JOIN sys.certificates c ON c.thumbprint=p.thumbprint LEFT JOIN sys.asymmetric_keys k ON k.thumbprint=p.thumbprint
UNION ALL SELECT DB_NAME(),N''''TRIGGER'''',CONVERT(nvarchar(128),object_id),CONVERT(nvarchar(128),parent_id),CONVERT(nvarchar(128),parent_class),CONVERT(nvarchar(128),is_disabled),CONVERT(nvarchar(128),is_instead_of_trigger) FROM sys.triggers
UNION ALL SELECT DB_NAME(),N''''TRIGGER_EVENT'''',CONVERT(nvarchar(128),object_id),CONVERT(nvarchar(128),type),N'''''''',CONVERT(nvarchar(128),is_first),CONVERT(nvarchar(128),is_last) FROM sys.trigger_events
UNION ALL SELECT DB_NAME(),N''''POLICY'''',CONVERT(nvarchar(128),object_id),N'''''''',N'''''''',CONVERT(nvarchar(128),is_enabled),CONVERT(nvarchar(128),is_schema_bound) FROM sys.security_policies
UNION ALL SELECT DB_NAME(),N''''PREDICATE'''',CONVERT(nvarchar(128),object_id),CONVERT(nvarchar(128),target_object_id),CONVERT(nvarchar(128),predicate_type),predicate_definition,CONVERT(nvarchar(128),operation) FROM sys.security_predicates
UNION ALL SELECT DB_NAME(),N''''SERVER_PRINCIPAL'''',p.name,ISNULL(SUSER_NAME(p.owning_principal_id),N''''''''),CONVERT(nvarchar(128),p.type),N'''''''',CONVERT(nvarchar(128),p.is_disabled) FROM sys.server_principals p WHERE DB_NAME()=''''master'''' AND p.name<>''''AiCimdCatalogSignerV2'''' AND (p.type IN(''''C'''',''''K'''') OR p.name LIKE ''''##MS[_]%'''' OR p.name=''''public'''' OR p.sid=0x01)
UNION ALL SELECT DB_NAME(),N''''SERVER_PERMISSION'''',s.name,ISNULL(SUSER_NAME(p.grantor_principal_id),N''''''''),CONCAT(p.class,N'''':'''',p.major_id),p.permission_name,CONVERT(nvarchar(128),p.state) FROM sys.server_permissions p JOIN sys.server_principals s ON s.principal_id=p.grantee_principal_id WHERE DB_NAME()=''''master'''' AND s.name<>''''AiCimdCatalogSignerV2'''' AND (s.type IN(''''C'''',''''K'''') OR s.name LIKE ''''##MS[_]%'''' OR s.name=''''public'''' OR s.sid=0x01)
UNION ALL SELECT DB_NAME(),N''''SERVER_MEMBER'''',SUSER_NAME(r.role_principal_id),s.name,N'''''''',N'''''''',N'''''''' FROM sys.server_role_members r JOIN sys.server_principals s ON s.principal_id=r.member_principal_id WHERE DB_NAME()=''''master'''' AND s.name<>''''AiCimdCatalogSignerV2'''' AND (s.type IN(''''C'''',''''K'''') OR s.name LIKE ''''##MS[_]%'''' OR s.name=''''public'''' OR s.sid=0x01)
UNION ALL SELECT DB_NAME(),N''''SERVER_OWNED'''',p.name,o.name,CONVERT(nvarchar(128),p.type),N'''''''',N'''''''' FROM sys.server_principals p JOIN sys.server_principals o ON o.principal_id=p.owning_principal_id WHERE DB_NAME()=''''master'''' AND o.name<>''''AiCimdCatalogSignerV2'''' AND (o.type IN(''''C'''',''''K'''') OR o.name LIKE ''''##MS[_]%'''' OR o.name=''''public'''');
 END;'';
 EXEC sys.sp_executesql @SystemSql;
 FETCH NEXT FROM SystemCatalogs INTO @SystemName;
END;
CLOSE SystemCatalogs;DEALLOCATE SystemCatalogs;
IF EXISTS(SELECT * FROM #CimdSystemPermissions EXCEPT SELECT * FROM @ExpectedSystemPermissions)
 OR EXISTS(SELECT * FROM @ExpectedSystemPermissions EXCEPT SELECT * FROM #CimdSystemPermissions)
 OR EXISTS(SELECT * FROM #CimdSystemObjects EXCEPT SELECT * FROM @ExpectedSystemObjects)
 OR EXISTS(SELECT * FROM @ExpectedSystemObjects EXCEPT SELECT * FROM #CimdSystemObjects)
 OR EXISTS(SELECT * FROM #CimdSystemAuthority EXCEPT SELECT * FROM @ExpectedSystemAuthority)
 OR EXISTS(SELECT * FROM @ExpectedSystemAuthority EXCEPT SELECT * FROM #CimdSystemAuthority)
 THROW 59620,''System public/guest permission or shipped-object drift.'',1;
DROP TABLE #CimdCheckedSids;DROP TABLE #CimdSystemPermissions;DROP TABLE #CimdSystemObjects;DROP TABLE #CimdSystemAuthority;

 IF (SELECT COUNT(*) FROM dbo.AiCaseDataDeployment WHERE Id=1)<>1
 OR (SELECT COUNT(*) FROM dbo.AiCimdProofControlV1 WHERE Id=1)<>1
 OR (SELECT COUNT(*) FROM dbo.AiCimdOAuthControlV1 WHERE Id=1)<>1
  THROW 59600,''Incomplete runtime binding or controls.'',1;
 SELECT Issuer,Resource,Contract,JavaTimeZone,SqlTimeZone,CONVERT(varchar(64),HASHBYTES(''SHA2_256'',CERTENCODED(CERT_ID(''AiCimdCatalogCertificateV2''))),2) AS CatalogCertificateSha256,CONVERT(varchar(170),@OwnerSid,2) AS CatalogOwnerSid FROM dbo.AiCaseDataDeployment WHERE Id=1;
END;';
CREATE ROLE AiCimdCatalogV2 AUTHORIZATION dbo;
GRANT VIEW DEFINITION TO AiCimdCatalogV2;
GRANT EXECUTE ON dbo.AiCimdAttestCatalogV2 TO AiCimdCatalogV2;
DECLARE @KeyPassword nvarchar(80)=CONVERT(nvarchar(36),NEWID())+N'aB9!';
DECLARE @Ddl nvarchar(max)=N'CREATE CERTIFICATE AiCimdCatalogCertificateV2 ENCRYPTION BY PASSWORD='+QUOTENAME(@KeyPassword,'''')+N' WITH SUBJECT=''Shale fixed catalog V2 metadata'',EXPIRY_DATE=''2030-01-01'';';
EXEC sys.sp_executesql @Ddl;
DECLARE @PublicCertificate varchar(max)=CONVERT(varchar(max),CERTENCODED(CERT_ID('AiCimdCatalogCertificateV2')),2);
SET @Ddl=N'USE master; CREATE CERTIFICATE AiCimdCatalogCertificateV2 FROM BINARY=0x'+CONVERT(nvarchar(max),@PublicCertificate)+N'; CREATE LOGIN AiCimdCatalogSignerV2 FROM CERTIFICATE AiCimdCatalogCertificateV2;
 REVOKE CONNECT SQL FROM AiCimdCatalogSignerV2;
 GRANT VIEW ANY DEFINITION,VIEW ANY DATABASE,AUTHENTICATE SERVER,CONNECT ANY DATABASE TO AiCimdCatalogSignerV2;';
EXEC sys.sp_executesql @Ddl;
SET @Ddl=N'ADD SIGNATURE TO dbo.AiCimdAttestCatalogV2 BY CERTIFICATE AiCimdCatalogCertificateV2 WITH PASSWORD='+QUOTENAME(@KeyPassword,'''')+N';';
EXEC sys.sp_executesql @Ddl;
ALTER CERTIFICATE AiCimdCatalogCertificateV2 REMOVE PRIVATE KEY;
SET @KeyPassword=NULL; SET @Ddl=NULL;
EXEC dbo.AiCimdAttestCatalogV2;
COMMIT TRANSACTION;
SELECT CONVERT(varchar(64),HASHBYTES('SHA2_256',CERTENCODED(CERT_ID('AiCimdCatalogCertificateV2'))),2) AS CatalogCertificateSha256,
 CONVERT(varchar(170),(SELECT owner_sid FROM sys.databases WHERE database_id=DB_ID()),2) AS CatalogOwnerSid;
END TRY BEGIN CATCH IF XACT_STATE()<>0 ROLLBACK TRANSACTION; THROW; END CATCH;
